def transform(grid):
    n = len(grid)
    out = [row[:] for row in grid]
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 2:
                orbit = {
                    (r, c), (c, n - 1 - r), (n - 1 - r, n - 1 - c), (n - 1 - c, r),
                    (r, n - 1 - c), (n - 1 - r, c), (c, r), (n - 1 - c, n - 1 - r),
                }
                known = [grid[rr][cc] for rr, cc in orbit if grid[rr][cc] != 2]
                if not known or len(set(known)) != 1:
                    raise ValueError(f"Cannot infer symmetric orbit at {(r, c)}")
                out[r][c] = known[0]
    return out
